import{c as e,Q as t,j as a,m as i}from"./chunks/framework.COywXlYp.js";const m=JSON.parse('{"title":"3.2.3.22","description":"","frontmatter":{"title":"3.2.3.22","layout":"doc"},"headers":[],"relativePath":"zh-CN/updatelog/beta/3/33022a4.md","filePath":"zh-CN/updatelog/beta/3/33022a4.md"}'),o={name:"zh-CN/updatelog/beta/3/33022a4.md"};function d(c,l,r,h,s,n){return t(),a("div",null,[...l[0]||(l[0]=[i('<h1 id="_3-2-3-22" tabindex="-1">3.2.3.22 <a class="header-anchor" href="#_3-2-3-22" aria-label="Permalink to &quot;3.2.3.22&quot;">​</a></h1><p>发布日期: 2026/04/19</p><p>这是一个开发测试更新，为<code>3.3.0</code>的开发周期的第3个版本，由原<code>3.2.1.20</code>升级而来，同步了现在的<code>3.2.1.20</code>和<code>3.2.2.21</code>。</p><h2 id="更新内容" tabindex="-1">更新内容 <a class="header-anchor" href="#更新内容" aria-label="Permalink to &quot;更新内容&quot;">​</a></h2><ul><li>修复以下问题：</li><li><ul><li>在反色或深色模式下，非windows默认样式的样式的菜单栏会显示异常：字体是当前风格的，但是背景是系统配色的。</li></ul></li><li><ul><li>在反色或深色模式下，非windows默认样式的标题栏有可能“卡壳”，深色模式标题栏是浅色的</li></ul></li><li><ul><li>清理缓存无法清理</li></ul></li><li>升级到Qt 6.11版本，修复或添加了一些显示：</li><li><ul><li>现在，最大化按钮会正常隐藏或变浅色，和3.1.0用的Qt 6.9版本的效果一样，而不是6.10的不起效果。</li></ul></li><li><ul><li>添加了沉浸式圆角菜单栏和下拉框，而不是直角下拉框和向没有抠图一样的圆角菜单栏。</li></ul></li><li>调整了响应延迟的下限，从1ms调整为50ms，以修复标题栏“卡壳”的问题</li><li>新增新的产品: <code>clickclean</code>，大幅精简了clickmouse，只保留连点器和其相关的设置，它的更新频率会比clickmouse慢，并且要手动检查更新。</li><li>现在开机自启动会在后台运行，若你是旧版本用户，需要在设置中重置开机自启动配置才能启用。</li><li>设置窗口图标变成了clickmouse的logo，而不是带有设置图标的clickmouse logo。</li><li><code>More settings</code>实验项的描述开头从<code>Can</code>变成了<code>To</code></li></ul><h2 id="clickclean更新内容" tabindex="-1">ClickClean更新内容 <a class="header-anchor" href="#clickclean更新内容" aria-label="Permalink to &quot;ClickClean更新内容&quot;">​</a></h2><ul><li>设置窗口图标变成了clickmouse的logo，而不是带有设置图标的clickmouse logo。</li></ul><h2 id="已知问题" tabindex="-1">已知问题 <a class="header-anchor" href="#已知问题" aria-label="Permalink to &quot;已知问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题描述</th><th>解决方案</th><th>影响版本</th><th>修复版本</th><th>状态</th><th>issue链接</th></tr></thead><tbody><tr><td>无</td><td>无</td><td>无</td><td>无</td><td>无</td><td>无</td></tr></tbody></table><h2 id="下载链接" tabindex="-1">下载链接 <a class="header-anchor" href="#下载链接" aria-label="Permalink to &quot;下载链接&quot;">​</a></h2><p><a href="https://github.com/xystudiocode/pyClickMouse/releases/tag/3.3.0.22alpha4" target="_blank" rel="noreferrer">点击下载</a></p>',11)])])}const _=e(o,[["render",d]]);export{m as __pageData,_ as default};
